sub:Head {
  this: a np:Nanopublication ;
    np:hasAssertion sub:assertion ;
    np:hasProvenance sub:provenance ;
    np:hasPublicationInfo sub:pubinfo .
}

sub:assertion {
  <https://w3id.org/delphi/resource/claim/real-organisms-score-plausible-is-near-worthless> a delphi:Claim ;
    rdfs:label "That real held-out organisms score plausible says almost nothing about whether the design scorer works, because negatives score plausible too." ;
    dct:description "STATUS: an observation reported in a single evaluation document (SCORER-EVALUATION.md, lines 14 and 45 to 47), from one blind family-out held-out run of every scorer version; it has not been replicated or checked independently here. The finding is that a high share of real organisms above the plausibility cut is uninformative, since negatives mostly land above the same cut. It does NOT establish that any scorer version fails, nor that any works; it does not rank the versions, and it says nothing about discrimination measured by other metrics. It only removes the real-organism pass rate as evidence of validity." ;
    delphi:hasEvidence <https://w3id.org/delphi/resource/evidence/real-organisms-score-plausible-is-near-worthless> .

  <https://w3id.org/delphi/resource/evidence/real-organisms-score-plausible-is-near-worthless> a delphi:EvidenceItem ;
    rdfs:label "Real held-out organisms pass the 0.5 plausibility cut almost always, while most negatives also pass it." ;
    dct:description "Taken from SCORER-EVALUATION.md: the held-out run (line 14) covers 168 families scored family-out. On the plausibility score, 98 to 99.6 % of real held-out organisms are at or above the 0.5 cut in every version (line 45), yet only 12 to 17 % of negatives fall below that cut (line 46). The document concludes each version is close to calling everything plausible (line 47). Two families with at least 3 real items fall under 80 % plausible (line 183), and one gulper eel example is described at line 186." ;
    schema:additionalProperty sub:pv-families, sub:pv-real-low, sub:pv-real-high, sub:pv-cut, sub:pv-neg-low, sub:pv-neg-high, sub:pv-min-items, sub:pv-share-threshold, sub:pv-eury-hit, sub:pv-eury-total, sub:pv-aspred-hit, sub:pv-aspred-total, sub:pv-eel-score, sub:pv-eel-dist .

  sub:pv-families a schema:PropertyValue ;
    schema:propertyID "held-out-families" ;
    schema:value 168 ;
    schema:description "Number of held-out families scored family-out in the blind run of every scorer version (SCORER-EVALUATION.md:14)." .

  sub:pv-real-low a schema:PropertyValue ;
    schema:propertyID "real-organisms-at-or-above-cut-lowest-percent" ;
    schema:value 98 ;
    schema:description "Lowest percentage across versions of real held-out organisms scoring at or above the cut (SCORER-EVALUATION.md:45)." .

  sub:pv-real-high a schema:PropertyValue ;
    schema:propertyID "real-organisms-at-or-above-cut-highest-percent" ;
    schema:value 99.6 ;
    schema:description "Highest percentage across versions of real held-out organisms scoring at or above the cut (SCORER-EVALUATION.md:45)." .

  sub:pv-cut a schema:PropertyValue ;
    schema:propertyID "plausibility-cut" ;
    schema:value 0.5 ;
    schema:description "Plausibility score cut used for both real organisms and negatives (SCORER-EVALUATION.md:45-46)." .

  sub:pv-neg-low a schema:PropertyValue ;
    schema:propertyID "negatives-below-cut-lowest-percent" ;
    schema:value 12 ;
    schema:description "Lowest percentage across versions of negatives scoring below the 0.5 cut (SCORER-EVALUATION.md:46)." .

  sub:pv-neg-high a schema:PropertyValue ;
    schema:propertyID "negatives-below-cut-highest-percent" ;
    schema:value 17 ;
    schema:description "Highest percentage across versions of negatives scoring below the 0.5 cut (SCORER-EVALUATION.md:46)." .

  sub:pv-min-items a schema:PropertyValue ;
    schema:propertyID "minimum-real-items-per-family" ;
    schema:value 3 ;
    schema:description "A family is listed only if it has at least this many real items (SCORER-EVALUATION.md:183)." .

  sub:pv-share-threshold a schema:PropertyValue ;
    schema:propertyID "family-plausible-share-threshold-percent" ;
    schema:value 80 ;
    schema:description "Families are flagged when fewer than this percentage of their real items score plausible (SCORER-EVALUATION.md:183)." .

  sub:pv-eury-hit a schema:PropertyValue ;
    schema:propertyID "eurypharyngidae-plausible-items" ;
    schema:value 3 ;
    schema:description "Real gulper eel (Eurypharyngidae) items scoring plausible (SCORER-EVALUATION.md:183)." .

  sub:pv-eury-total a schema:PropertyValue ;
    schema:propertyID "eurypharyngidae-real-items" ;
    schema:value 5 ;
    schema:description "Total real gulper eel (Eurypharyngidae) items (SCORER-EVALUATION.md:183)." .

  sub:pv-aspred-hit a schema:PropertyValue ;
    schema:propertyID "aspredinidae-plausible-items" ;
    schema:value 20 ;
    schema:description "Real banjo catfish (Aspredinidae) items scoring plausible (SCORER-EVALUATION.md:183)." .

  sub:pv-aspred-total a schema:PropertyValue ;
    schema:propertyID "aspredinidae-real-items" ;
    schema:value 29 ;
    schema:description "Total real banjo catfish (Aspredinidae) items (SCORER-EVALUATION.md:183)." .

  sub:pv-eel-score a schema:PropertyValue ;
    schema:propertyID "fs-05942-plausibility-score" ;
    schema:value 0.15 ;
    schema:description "Plausibility score of the gulper eel example fs-05942 (SCORER-EVALUATION.md:186)." .

  sub:pv-eel-dist a schema:PropertyValue ;
    schema:propertyID "fs-05942-nearest-neighbour-distance" ;
    schema:value 0.96 ;
    schema:description "Distance from fs-05942 to its nearest remaining neighbour, the cutlassfish Lepturacanthus savala, once its family is removed (SCORER-EVALUATION.md:186)." .
}

